add('sam-nu-hoang-la-cay-gi','Sâm Nữ Hoàng: hiểu đúng về giống cây và tên gọi','VỀ GIỐNG SÂM','farm-reference','Ảnh tư liệu cây MS Nữ Hoàng · Nguồn HTV, Kiều Nhi.','Một tên gọi quen thuộc trên thị trường, nhưng để hiểu nguyên liệu, hãy bắt đầu từ tên khoa học và nguồn giống.',[
('Tên gọi thương mại và tên khoa học','Các tư liệu trong bộ hồ sơ đề cập cây MS Nữ Hoàng thuộc loài Rumex crispus L., thường được gọi là dương đề nhăn. Kew ghi nhận Rumex crispus thuộc họ Polygonaceae. Tên “sâm” trong tên thương mại không có nghĩa đây là nhân sâm thuộc chi Panax.'),
('Nhìn cây từ lá đến rễ','Tư liệu hình ảnh cho thấy cây có tán lá xanh, bộ rễ phát triển và phần củ có thể được làm sạch, cắt lát để sơ chế. Hình dáng một củ hay một lá riêng lẻ không đủ để xác nhận đúng giống thương mại; cần đối chiếu hồ sơ giống và đơn vị cung cấp.'),
('Vì sao nguồn giống cần được kể rõ?','Nguồn giống là điểm bắt đầu của câu chuyện nguyên liệu. Khi tìm hiểu sản phẩm, khách hàng nên xem cả nơi trồng, thời điểm thu hoạch, bộ phận dùng và quy trình chế biến. Bốn thông tin này giúp việc so sánh sâm tươi, sâm khô và cao sâm có ý nghĩa hơn.'),
('Từ giống cây đến Sâm Nữ Hoàng Đỗ Thị Tuyết','Theo thông tin hộ kinh doanh cung cấp, giống được nhập và trồng theo sự cho phép của MS Thiên Ngọc, gắn với bà Võ Thị Ngọc. Diện tích do hộ kinh doanh cung cấp là 3 ha tại Hà Nội. Ảnh tư liệu trong bài minh họa giống cây, không phải ảnh xác nhận hai vùng trồng này.')],['plant','author','htv'],['vo-thi-ngoc-ms-thien-ngoc','nguon-giong-va-truy-xuat'])
add('vo-thi-ngoc-ms-thien-ngoc','Bà Võ Thị Ngọc và hành trình phát triển MS Nữ Hoàng','CON NGƯỜI & GIỐNG CÂY','scientist','Bà Võ Thị Ngọc · Ảnh Minh Đảm / Báo Nông nghiệp và Môi trường.','Tìm hiểu người nghiên cứu giống cây qua tư liệu báo chí và mối liên hệ với nguồn nguyên liệu của hộ kinh doanh.',[
('Nhân vật được nhắc đến trong các tư liệu','Bài viết của Báo Nông nghiệp và Môi trường giới thiệu bà Võ Thị Ngọc là tác giả chính nghiên cứu cây MS Nữ Hoàng, gắn với Công ty TNHH Lương thực MS Thiên Ngọc. Bài báo sử dụng danh xưng GS.TS và đồng thời mô tả việc bà được phong học vị, học hàm danh dự. Trang này dẫn lại thông tin theo nguồn, để bạn đọc có thể kiểm tra nguyên văn.'),
('Từ nghiên cứu đến nhân giống','Các tư liệu mô tả quá trình phát triển nguồn giống, mở rộng vườn ươm và liên kết vùng nguyên liệu. Giá trị của hành trình này nằm ở việc đưa giống cây vào một chuỗi có thể theo dõi: nguồn cây con, người trồng, khu vực canh tác và đầu ra chế biến.'),
('Vai trò của Đỗ Thị Tuyết','Hộ kinh doanh Đỗ Thị Tuyết là đơn vị trồng và phát triển sản phẩm được giới thiệu trên website này. Theo chủ hộ, đơn vị nhập giống và trồng với sự cho phép của MS Thiên Ngọc. Bà Võ Thị Ngọc và bà Đỗ Thị Tuyết là hai người có vai trò khác nhau; ảnh trong bài là ảnh bà Võ Thị Ngọc.'),
('Đọc tiếp theo dòng tư liệu','Để hiểu đầy đủ câu chuyện, nên đọc tiếp thông tin về nhận diện giống cây và truy xuất nguồn gốc. Những bài viết được liên kết dưới đây bổ sung bối cảnh, thay vì chỉ nhìn vào một hình ảnh hay một danh xưng.')],['author','seed'],['sam-nu-hoang-la-cay-gi','nguon-giong-va-truy-xuat'])
add('doc-hieu-thanh-phan-sam','Đọc hiểu số liệu thành phần: đúng mẫu, đúng đơn vị','THÀNH PHẦN & TƯ LIỆU','slices-reference','Ruột củ MS Nữ Hoàng được làm sạch, cắt lát · Ảnh Kiều Nhi / HTV.','Một con số thành phần chỉ có ý nghĩa khi biết đó là mẫu gì, được xử lý ra sao và được báo cáo bằng đơn vị nào.',[
('Những số liệu đã được báo chí công bố','Bài “Sâm Nữ Hoàng, tiềm năng mới của ngành dược” đưa ra số liệu trên mẫu củ tươi: polyphenol toàn phần 1,47%; polysaccharide hòa tan 5,5%; saponin tổng số 1,34%; flavonoid 957 mg/kg. Đây là số liệu được bài báo dẫn, không phải kết quả kiểm nghiệm của lô hàng Đỗ Thị Tuyết.'),
('Không trộn mẫu tươi, khô và cao chiết','Các bài trong bộ tư liệu nêu những số liệu khác nhau cho lá, hoa, củ và nguyên liệu sau xử lý. Mất nước khi làm khô hoặc thay đổi quy trình chiết có thể làm thay đổi cách biểu thị hàm lượng. Vì vậy không nên đặt hai tỷ lệ cạnh nhau rồi kết luận sản phẩm nào tốt hơn khi chưa có cùng loại mẫu và cùng phương pháp.'),
('Có hợp chất không đồng nghĩa có hiệu quả điều trị','Sự hiện diện của một nhóm hợp chất là thông tin thành phần. Nó không tự chứng minh tác dụng điều trị của một sản phẩm cụ thể trên người. Website không chuyển các kết quả thành phần này thành lời hứa chữa bệnh hoặc công dụng của rượu sâm.'),
('Thông tin nên có trên hồ sơ sản phẩm','Một hồ sơ có ích cần tên mẫu, bộ phận cây, trạng thái mẫu, số lô, ngày thử nghiệm, phương pháp và đơn vị kết quả. Khi hộ kinh doanh bổ sung hồ sơ của chính sản phẩm, các số liệu sẽ được đặt cạnh đúng mã hàng để người đọc đối chiếu.')],['analysis','seed','htv'],['sam-nu-hoang-la-cay-gi','sam-tuoi-sam-kho-cao-sam'])
add('nguon-giong-va-truy-xuat','Từ cây giống đến sản phẩm: những thông tin cần theo dõi','VÙNG TRỒNG & NGUỒN GỐC','seedlings','Cây giống được chọn lọc · Ảnh Kiều Nhi / Báo Nông nghiệp và Môi trường.','Câu chuyện vùng trồng thuyết phục nhất khi mỗi bước đều có thông tin để kiểm tra.',[
('Bắt đầu bằng nguồn cây giống','Báo Nông nghiệp và Môi trường đề cập rủi ro từ cây giống không rõ nguồn gốc và nhu cầu quản lý giống MS Nữ Hoàng. Với người trồng, hồ sơ bên cung cấp, thời điểm nhận cây và mã lô giống là những dữ liệu cần được lưu cùng nhau.'),
('Ghi chép trong quá trình trồng','Mỗi khu vực nên có nhật ký về thời điểm xuống giống, chăm sóc, vật tư sử dụng và thu hoạch. Khi cần kiểm tra một lô nguyên liệu, nhật ký giúp kết nối cây giống với khu đất và thời gian cụ thể. Đây là cấu trúc thông tin đề xuất cho website, không phải tuyên bố hộ kinh doanh đã được chứng nhận một tiêu chuẩn.'),
('Tách lô sau thu hoạch','Nguyên liệu tươi, nguyên liệu sấy và cao cô đặc cần hồ sơ riêng. Mã lô, khối lượng, ngày xử lý và quy cách đóng gói giúp khách hàng biết mình đang đọc thông tin về đúng sản phẩm.'),
('Thông tin hiện có của hộ kinh doanh','Chủ hộ cung cấp tổng diện tích 3 ha: 2 ha tại Sóc Sơn và 1 ha tại Ứng Hòa. Website đã có trang riêng cho vùng trồng và có thể tiếp nhận thêm ảnh thực địa, nhật ký mùa vụ, mã lô khi được cung cấp.')],['seed'],['tu-vuon-trong-den-thu-hoach','sam-nu-hoang-la-cay-gi'])
add('tu-vuon-trong-den-thu-hoach','Từ vườn trồng đến thu hoạch: một hành trình nguyên liệu','NHẬT KÝ TƯ LIỆU','field','Vườn trong bài thu hoạch tại HTX Tâm Ngọc · QueenGinseng Việt Nam. Không phải vùng trồng Đỗ Thị Tuyết.','Những hình ảnh thực địa giúp nhìn cây sâm trong bối cảnh canh tác, trước khi trở thành sản phẩm đóng gói.',[
('Một góc nhìn từ tư liệu thu hoạch','Bài viết của QueenGinseng Việt Nam ghi lại hoạt động thu hoạch tại HTX Tâm Ngọc. Hình ảnh vườn, cây và người thu hái bổ sung góc nhìn trực quan cho người chưa từng thấy giống cây này ngoài thực địa.'),
('Lá và củ là hai dòng nguyên liệu','Việc nói rõ bộ phận cây giúp người xem tránh nhầm giữa sản phẩm từ lá và sản phẩm từ củ. Một loại cao có thể dùng lá làm nguyên liệu; hình củ sâm trên trang giới thiệu không đủ để suy ra thành phần bên trong hũ.'),
('Từ ảnh minh họa đến nhật ký của chính vùng trồng','Website sử dụng ảnh tư liệu có nguồn để giải thích giống cây. Với hai vùng trồng của hộ kinh doanh tại Hà Nội, nhật ký riêng sẽ cần ảnh có địa điểm, ngày chụp và thông tin mùa vụ. Các ảnh ngoài đơn vị luôn được chú thích để không bị hiểu nhầm.'),
('Khám phá sản phẩm theo dạng nguyên liệu','Nếu bạn muốn tìm hiểu sâu hơn, bài so sánh sâm tươi, sâm khô và cao sâm giải thích cách đọc quy cách. Bộ sưu tập Ngự Vị Nữ Hoàng Tưu có trang riêng cho từng dạng chai, bình và trống gỗ sồi.')],['harvest','cao'],['sam-tuoi-sam-kho-cao-sam','nguon-giong-va-truy-xuat'])
add('sam-tuoi-sam-kho-cao-sam','Sâm tươi, sâm khô, cao sâm: đọc quy cách trước khi chọn','CẨM NANG SẢN PHẨM','slices-reference','Ảnh tư liệu củ cắt lát · HTV / Kiều Nhi; không phải ảnh thành phẩm sâm khô đóng gói.','Ba dạng sản phẩm cần ba cách đọc thông tin khác nhau. Khối lượng giống nhau không có nghĩa lượng nguyên liệu tương đương.',[
('Sâm tươi: hỏi rõ bộ phận và khối lượng','Với nguyên liệu tươi, hãy xác nhận đây là củ hay lá, khối lượng trước hay sau làm sạch và thời điểm giao nhận. Bản thiết kế hiện dùng quy cách củ tươi 500g và 1kg để minh họa thao tác lựa chọn.'),
('Sâm khô: nguyên củ hay cắt lát?','Dạng cắt lát thuận tiện cho việc quan sát bề mặt và định lượng theo khối lượng. Tuy nhiên màu sắc không thay thế thông tin độ ẩm, phương pháp sơ chế hoặc chất lượng lô hàng. Bản mẫu dùng quy cách 100g, 250g và 500g; hình cắt lát là tư liệu tham khảo, sẽ thay bằng ảnh thành phẩm của hộ kinh doanh.'),
('Cao sâm: đọc thành phần thực tế','Trang sản phẩm tham khảo của Sâm Nữ Hoàng Việt Nam mô tả cao làm từ lá sâm kết hợp mật ong, khối lượng 100g. Thông tin này cho thấy cần đọc thành phần thay vì mặc định mọi loại cao đều làm từ củ. Công thức của sản phẩm Đỗ Thị Tuyết sẽ được xác nhận riêng.'),
('Giá trong bản thiết kế được hiểu thế nào?','Các mức giá hiển thị có nhãn giả định để duyệt. Cao 100g dùng mốc tham khảo 790.000đ từ một đơn vị khác; sâm tươi, sâm khô và rượu có mức giá dựng mẫu. Chúng phục vụ việc xem giao diện, chọn quy cách và tính tổng, chưa phải báo giá chính thức.')],['cao','price'],['doc-hieu-thanh-phan-sam','chon-quy-cach-ngu-vi'])
add('chon-quy-cach-ngu-vi','Ngự Vị Nữ Hoàng Tưu: năm kiểu dáng, một bộ sưu tập','CẨM NANG QUÀ TẶNG','gourd','Ảnh sản phẩm do hộ kinh doanh cung cấp, đã xử lý nền để trình bày.','Từ chai gọn đến dáng trống gỗ sồi, mỗi kiểu bao bì tạo nên một cách trưng bày riêng.',[
('Chai thủy tinh và bình hồ lô','Chai thủy tinh tạo cảm giác gọn, phù hợp bố cục hộp quà. Bình hồ lô có hai bầu tròn và nút thủy tinh, mang dáng vẻ trang trí nổi bật. Khi lựa chọn, nên đối chiếu cả kích thước đặt trên bàn và nhu cầu đóng gói, thay vì chỉ xem dung tích.'),
('Bình dáng trống và bình đa giác','Bình thủy tinh dáng trống có mặt tròn và vòi rót phía trước; bình đa giác nổi bật với các cạnh và mảng thủy tinh. Hai dáng bình có trang ảnh riêng để quan sát chi tiết từ nhiều góc.'),
('Trống gỗ sồi là điểm nhấn riêng','Thân gỗ, đai kim loại, vòi rót và chân đế tạo nên một hình khối khác biệt. Từ ảnh bao bì không thể suy ra thời gian ủ hay đặc tính hương vị của rượu. Website giới thiệu đúng đặc điểm nhìn thấy, còn hồ sơ rượu cần xác nhận với hộ kinh doanh.'),
('Cách dùng bộ chọn quy cách','Mỗi trang có dung tích mẫu, nồng độ giả định, số lượng và tổng tạm tính. Bạn có thể lưu vào danh sách dự toán rồi tải xuống để trao đổi. Đây là bản duyệt; không có thao tác thanh toán hay gửi đơn tự động. Rượu chỉ dành cho người từ 18 tuổi.')],[],['trong-ruou-go-soi','sam-tuoi-sam-kho-cao-sam'])
add('trong-ruou-go-soi','Trống rượu gỗ sồi: vẻ đẹp từ chất liệu và hình khối','NGỰ VỊ NỮ HOÀNG TƯU','oak','Ảnh trống gỗ sồi do hộ kinh doanh cung cấp, đã tách nền.','Một thiết kế có sự hiện diện rõ ràng trên bàn trưng bày: sắc gỗ ấm, đai kim loại và vòi rót.',[
('Những chi tiết có thể quan sát','Ảnh sản phẩm thể hiện thân trống tròn, các đai giữ thân, vòi kim loại ở phía trước và chân đế gỗ. Trang chi tiết còn giữ các góc ảnh gốc để người xem đối chiếu với ảnh đã xử lý nền.'),
('Chọn không gian trước khi chọn quy cách','Một mẫu trưng bày cần tính cả khoảng trống thao tác với vòi và vị trí đặt ly. Khi đặt làm quà, hãy trao đổi thêm kích thước hộp, khả năng vận chuyển và cách cố định chân đế. Những thông số này cần được xác nhận theo mẫu thực tế.'),
('Bao bì gỗ không xác nhận quá trình ủ','Hình ảnh trống gỗ không đủ chứng minh rượu đã được ủ trong gỗ bao lâu. Vì vậy nội dung giới thiệu tập trung vào kiểu bao bì và thiết kế. Thời gian ngâm, thành phần và nồng độ thực tế sẽ được cập nhật từ hồ sơ sản phẩm.'),
('Hai lựa chọn trong bản duyệt','Bản mẫu trình bày dung tích 5 lít và 10 lít với giá giả định để xem cách bố trí bảng chọn. Trước khi dùng website bán hàng chính thức, chủ hộ sẽ chỉnh lại dung tích, nồng độ, đơn giá và điều kiện giao nhận theo sản phẩm đang cung cấp.')],[],['chon-quy-cach-ngu-vi','nguon-giong-va-truy-xuat'])
